import os, pty, sys, time, select, fcntl, termios, struct, signal
sys.path.insert(0,'/tmp/rec')
from term import render

def runx(args, keys=(0.8,), rows=30, cols=100, settle=0.8, exe='./executable', delay=0.05, kill=True):
    """Like drive.run but returns (raw, exitinfo). exitinfo = ('exit',code)|('sig',n)|('killed',None)"""
    pid, fd = pty.fork()
    if pid == 0:
        env = dict(os.environ); env['TERM']='xterm-256color'
        env['COLUMNS']=str(cols); env['LINES']=str(rows)
        os.execvpe(exe, [exe]+list(args), env)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0,0))
    buf=b''
    def pump(t):
        nonlocal buf
        end=time.time()+t
        while time.time()<end:
            r,_,_=select.select([fd],[],[],0.02)
            if r:
                try: d=os.read(fd,65536)
                except OSError: return False
                if not d: return False
                buf+=d
        return True
    pump(settle)
    for k in keys:
        if isinstance(k,(int,float)): pump(k); continue
        try: os.write(fd, k if isinstance(k,bytes) else k.encode())
        except OSError: pass
        pump(delay)
    pump(settle)
    # check if already exited
    st=None
    try:
        wpid, status = os.waitpid(pid, os.WNOHANG)
        if wpid==pid: st=status
    except ChildProcessError:
        st=0
    if st is None:
        if kill:
            try: os.kill(pid, signal.SIGKILL)
            except Exception: pass
            try: os.waitpid(pid,0)
            except Exception: pass
            return buf, ('killed', None)
        return buf, ('running', None)
    if os.WIFEXITED(st): return buf, ('exit', os.WEXITSTATUS(st))
    if os.WIFSIGNALED(st): return buf, ('sig', os.WTERMSIG(st))
    return buf, ('?', st)

def show(args, keys=(0.8,), rows=30, cols=100, **kw):
    raw, ex = runx(args, keys, rows=rows, cols=cols, **kw)
    t = render(raw, rows, cols)
    print(t.text())
    print('EXITINFO:', ex)
    print('RAWLEN:', len(raw))
    return t, raw, ex
